sys_script_include.script:
var getWeatherDetails = Class.create();
getWeatherDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getWeatherDetails: function(cityName) {

        try {
            var r = new sn_ws.RESTMessageV2('x_938076_now_utils.Weather API', 'Default GET');
            r.setStringParameterNoEscape('city', 'Chennai');
            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();
            var getCompleteBody = JSON.parse(responseBody);
            var getAstro = getCompleteBody.current.astro;
            var getLocDetails = getCompleteBody.location;

            var finalPayload = {};

            finalPayload.locationDetails = getLocDetails;
            finalPayload.astroDetails = getAstro;

            return finalPayload;

        } catch (ex) {
            var message = ex.message;
        }

    },

    type: 'getWeatherDetails'
});
